  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])

    # build maps
    node_map = {}
    children = {}
    for n in nodes:
        nid = n['id']
        node_map[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].append(n['id'])

    all_ids = list(node_map.keys())
    # order: depth descending, then id ascending
    order = sorted(all_ids, key=lambda x: (-node_map[x]['depth'], x))

    removed = []
    retained = set(all_ids)

    for nid in order:
        if nid not in retained:
            continue
        node = node_map[nid]
        if not node['removable'] or node['symbol'] in required:
            continue
        # must not have retained children
        if any(c in retained for c in children.get(nid, [])):
            continue
        # simulate removal
        temp = retained - {nid}
        # check all required symbols still present
        if all(any(node_map[rid]['symbol'] == sym for rid in temp) for sym in required):
            removed.append(nid)
            retained = temp

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained)
    }"
}
